  PD.demo.mapFx = function (phone, o) {
    o = o || {}; var map = phone.querySelector('canvas.pd-map'), W = map.clientWidth, H = map.clientHeight, ts = 32, s = 2;
    var ox = Math.round(W / 2 - 6.5 * ts), oy = Math.round(H * .46 - 15.5 * ts);
    var cv = document.createElement('canvas'); cv.className = 'pd-mapfx'; cv.width = W; cv.height = H; map.parentNode.insertBefore(cv, map.nextSibling);
    var g = cv.getContext('2d'); g.imageSmoothingEnabled = false; var t0 = performance.now();
    var cell = function (x, y) { return [ox + x * ts, oy + y * ts]; };
    var glow = function (x, y, r, col, a) { var gr = g.createRadialGradient(x, y, 0, x, y, r); gr.addColorStop(0, col.replace('A', a)); gr.addColorStop(.5, col.replace('A', a * .45)); gr.addColorStop(1, col.replace('A', 0)); g.fillStyle = gr; g.fillRect(x - r, y - r, r * 2, r * 2); };
    function frame(now) {
      var t = now - t0; g.clearRect(0, 0, W, H);
      if (o.prism) { var p = cell(7, 15), im = fimg('prism'), f = [0, 0, 0, 1, 0, 0, 1, 1][Math.floor(t / 1000) % 8]; if (im.complete) g.drawImage(im, f * 12, (Math.floor(t / 120) % 4) * 15, 12, 15, p[0] + 4 * s, p[1] + ts - 15 * s, 12 * s, 15 * s);
        if (o.heart) { var hi = fimg('heart'); if (hi.complete) g.drawImage(hi, (Math.floor(t / 400) % 2) * 7, 0, 7, 7, p[0] + 9 * s, p[1] + ts - 22 * s + (Math.floor(t / 400) % 2) * s, 7 * s, 7 * s); } }
      if (o.ghost) { var q = cell(5, 14), gh = img('ghost'), bob = Math.round(Math.sin(t / 500) * 2) * s; g.globalCompositeOperation = 'lighter'; glow(q[0] + ts / 2, q[1] + ts / 2 + bob, ts * 1.6, 'rgba(150,210,255,A)', .22 + .06 * Math.sin(t / 300)); g.globalCompositeOperation = 'source-over';
        if (gh.complete) { g.globalAlpha = .82; g.drawImage(gh, 0, 0, 14, 15, q[0] + 1 * s, q[1] + ts - 15 * s + bob, 14 * s, 15 * s); g.globalAlpha = 1; }
        if (o.heart) { var hj = fimg('heart'); if (hj.complete) g.drawImage(hj, (Math.floor(t / 400) % 2) * 7, 0, 7, 7, q[0] + 10 * s, q[1] + ts - 22 * s + bob, 7 * s, 7 * s); } }
      if (o.chains) { var a = cell(6, 15), b = cell(3, 16), ax = a[0] + ts / 2, ay = a[1] + ts / 2, bx = b[0] + ts / 2, by = b[1] + ts / 2, c = (t % 1800) / 600, len = Math.hypot(bx - ax, by - ay), ang = Math.atan2(by - ay, bx - ax), reach = Math.min(1, c), n = Math.floor(len * reach / (5 * s)), li = fimg('link');
        g.globalCompositeOperation = 'lighter'; glow(ax + Math.cos(ang) * len * reach, ay + Math.sin(ang) * len * reach, 18, 'rgba(120,216,255,A)', .35); g.globalCompositeOperation = 'source-over';
        for (var i = 0; i < n; i++) { g.save(); g.translate(ax + Math.cos(ang) * i * 5 * s, ay + Math.sin(ang) * i * 5 * s); g.rotate(ang); if (li.complete) g.drawImage(li, (i % 2) * 6, 0, 6, 4, -3 * s, -2 * s, 6 * s, 4 * s); g.restore(); }
        var hk = fimg('hook'); g.save(); g.translate(ax + Math.cos(ang) * len * reach, ay + Math.sin(ang) * len * reach); g.rotate(ang + Math.PI / 2); if (hk.complete) g.drawImage(hk, -3.5 * s, -3.5 * s, 7 * s, 7 * s); g.restore(); }
      if (o.bolt != null) { var k = o.bolt < 0 ? Math.floor(t / 900) % 12 : o.bolt, pr = (t % 900) / 700, from = cell(6, 15), to = cell(9, 12), bi = fimg('bolts');
        if (pr <= 1) { var x = from[0] + ts / 2 + (to[0] - from[0]) * pr, y = from[1] + ts / 2 + (to[1] - from[1]) * pr; g.fillStyle = WANDS.trail[k]; for (var j = 1; j < 5; j++) { g.globalAlpha = .5 - j * .1; g.fillRect(Math.round(x - (to[0] - from[0]) * j * .03) - s, Math.round(y - (to[1] - from[1]) * j * .03) - s, 2 * s, 2 * s); } g.globalAlpha = 1;
          if (bi.complete) g.drawImage(bi, (Math.floor(t / 90) % 2) * 8, k * 8, 8, 8, Math.round(x) - 4 * s, Math.round(y) - 4 * s, 8 * s, 8 * s); }
        if (o.boltLabel) o.boltLabel.textContent = WANDS[o.lang || 'ru'][k]; }
      requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  };

